# Day 10 transactions attributes
schemes = set(day10['card_scheme'].unique())
credits = set(day10['is_credit'].unique())
acis = set(day10['aci'].unique())
intracountry_vals = set((day10['issuing_country']==day10['acquirer_country']).unique())

def volume_match(rule_vol, actual=113260):
    if rule_vol is None: return True
    # parse
    if rule_vol == '100k-1m':
        return 100000 <= actual <= 1000000
    if rule_vol == '10k-100k':
        return 10000 <= actual <= 100000
    if rule_vol == '<10k':
        return actual < 10000
    if rule_vol == '>1m':
        return actual > 1000000
    if rule_vol == '5m-10m':
        return 5000000 <= actual <= 10000000
    return False

def fraud_match(rule_fraud, actual=10.313):
    if rule_fraud is None: return True
    # e.g. '7.7%-8.3%'
    s = rule_fraud.replace('%','')
    if '-' in s:
        a, bb = s.split('-')
        return float(a) <= actual <= float(bb)
    if s.startswith('<'):
        return actual < float(s[1:])
    if s.startswith('>'):
        return actual > float(s[1:])
    return False

applicable = []
for r in fees:
    at = r['account_type']
    if at and acct not in at:
        continue
    m = r['merchant_category_code']
    if m and mcc not in m:
        continue
    cd = r['capture_delay']
    if cd is not None and cd != '<3':
        continue
    if r['card_scheme'] not in schemes:
        continue
    if r['is_credit'] is not None and r['is_credit'] not in credits:
        continue
    if r['aci'] and not (set(r['aci']) & acis):
        continue
    if r['intracountry'] is not None and r['intracountry'] not in intracountry_vals:
        continue
    if not volume_match(r['monthly_volume']):
        continue
    if not fraud_match(r['monthly_fraud_level']):
        continue
    applicable.append(r['ID'])

print(len(applicable))
