    if mfl is not None:
        if '<' in mfl:
            v=float(mfl.replace('<','').replace('%',''))
            if not (10.3<v): return False
        elif '>' in mfl:
            v=float(mfl.replace('>','').replace('%',''))
            if not (10.3>v): return False
        elif '-' in mfl:
            lo,hi=mfl.split('-'); lo=float(lo.replace('%','')); hi=float(hi.replace('%',''))
            if not (lo<=10.3<=hi): return False
    mv = rule['monthly_volume']
    if mv is not None:
        def p(v): return int(v.replace('k','000').replace('m','000000'))
        if '<' in mv:
            if not (113260<p(mv.replace('<',''))): return False
        elif '>' in mv:
            if not (113260>p(mv.replace('>',''))): return False
        elif '-' in mv:
