import pandas as pd, json
fees = json.load(open('data/fees.json'))
df = pd.read_csv('data/payments.csv')
m = df[(df.merchant=='Belles_cookbook_store') & (df.year==2023) & (df.day_of_year>=60) & (df.day_of_year<=90)]

account_type='R'
mcc=5942
capture_delay='1'  # numeric, means <3
vol=m.eur_amount.sum()
fraud=m[m.has_fraudulent_dispute].eur_amount.sum()/vol
schemes=set(m.card_scheme.unique())
credits=set(m.is_credit.unique())
acis=set(m.aci.unique())
# intracountry: all False here
intracountry_vals={False}

def cap_match(rule_cd):
    if rule_cd is None: return True
    # merchant capture_delay = 1 day -> '<3'
    # map
    if rule_cd=='<3': return True
    if rule_cd=='immediate': return False
    if rule_cd=='manual': return False
    if rule_cd=='3-5': return False
    if rule_cd=='>5': return False
    return False

def vol_match(rule_v):
    if rule_v is None: return True
    def parse(s):
        s=s.replace('k','000').replace('m','000000')
        return float(s)
    if '-' in rule_v:
        lo,hi=rule_v.split('-')
        return parse(lo)<=vol<=parse(hi)
    if rule_v.startswith('>'):
        return vol>parse(rule_v[1:])
    if rule_v.startswith('<'):
        return vol<parse(rule_v[1:])
    return False

def fraud_match(rule_f):
    if rule_f is None: return True
    fr=fraud*100
    if '-' in rule_f:
        lo,hi=rule_f.replace('%','').split('-')
        return float(lo)<=fr<=float(hi)
    if rule_f.startswith('>'):
        return fr>float(rule_f[1:].replace('%',''))
    if rule_f.startswith('<'):
        return fr<float(rule_f[1:].replace('%',''))
    return False

matched=[]
for f in fees:
    if f['card_scheme'] not in schemes: continue
    if f['account_type'] and account_type not in f['account_type']: continue
    if not cap_match(f['capture_delay']): continue
    if not fraud_match(f['monthly_fraud_level']): continue
    if not vol_match(f['monthly_volume']): continue
    if f['merchant_category_code'] and mcc not in f['merchant_category_code']: continue
    if f['is_credit'] is not None and f['is_credit'] not in credits: continue
    if f['aci'] and not (set(f['aci']) & acis): continue
    if f['intracountry'] is not None and f['intracountry'] not in intracountry_vals: continue
    matched.append(f['ID'])

print(len(matched))
print(','.join(map(str,matched)))
